1	// 06 · Acute:Chronic Workload Ratio: the basics everyone should know.
2	// Composition: hook = giant figure left with headline column right; takeaway = huge
3	// headline, short rule, question below; alignment = left.
4	
5	module.exports = {
6	  num: 6,
7	  slug: "acute-chronic-workload-ratio",
8	  title: "Acute:Chronic Workload Ratio",
9	  category: "Recovery & Load Management",
10	  palette: "forest",
11	  hero: { layout: "ratio-scale-band", concept: "A single ratio scale from 0.5 to 2.0: the familiar 'close to usual' band and the spike zone from 1.5 up" },
12	  compose: { hook: "figure-left", takeaway: "headline-rule-question", align: "left" },
13	  oneIdea: "Sudden spikes in load are the risk. The ratio is a way to spot them, not a verdict.",
14	  question: "Where in our calendar does load jump without anyone planning it?",
15	  caveats: `ACWR is contested. Present 0.8-1.3 and 1.5 as where the early studies drew lines, not as validated thresholds. Never cite 1.5 to Hulin et al.; their own "very high" cut-off was different. Gabbett's group argues coupling makes little practical difference (Windt & Gabbett 2019; Gabbett et al. 2019); Lolli and colleagues and Impellizzeri and colleagues disagree. If someone asks "should we stop using it?": the defensible position is that it is a reasonable flag for big week-to-week jumps, read alongside the athlete and the plan, and never an injury predictor on its own.`,
16	  sources: [
17	    { id: "gabbett2016", cite: "Gabbett TJ. The training-injury prevention paradox: should athletes be training smarter and harder? Br J Sports Med. 2016;50(5):273-280. doi:10.1136/bjsports-2015-095788", grade: "influential narrative review; thresholds are descriptive, not validated", found: "external (cited across Zotero items, e.g. Williams 2017)", supports: "The 0.8-1.3 'sweet spot' and the 1.5 'danger zone' framing." },
18	    { id: "hulin2016", cite: "Hulin BT, Gabbett TJ, Lawson DW, Caputi P, Sampson JA. The acute:chronic workload ratio predicts injury: high chronic workload may decrease injury risk in elite rugby league players. Br J Sports Med. 2016;50(4):231-236. doi:10.1136/bjsports-2015-094817", grade: "single-cohort observational study", found: "Zotero", supports: "Players with high chronic load coped with moderate ratios; injury risk rose with spikes in acute load." },
19	    { id: "impellizzeri2020", cite: "Impellizzeri FM, Ward P, Coutts AJ, Bornn L, McCall A. Training load and injury part 2: questionable research practices hijack the truth and mislead well-intentioned clinicians. J Orthop Sports Phys Ther. 2020;50(10):577-584. doi:10.2519/jospt.2020.9211", grade: "methodological critique", found: "Zotero", supports: "Results across ACWR studies are 'inconsistent and often confusing' (p. 578)." },
20	    { id: "lolli2019", cite: "Lolli L, Batterham AM, Hawkins R, et al. Mathematical coupling causes spurious correlation within the conventional acute-to-chronic workload ratio calculations. Br J Sports Med. 2019;53(15):921-922. doi:10.1136/bjsports-2017-098110", grade: "methodological critique with simulation", found: "external", supports: "Because the latest week sits in both the acute and the chronic load, the two correlate (~0.5) from the arithmetic alone." },
21	    { id: "windt2019", cite: "Windt J, Gabbett TJ. Is it all for naught? What does mathematical coupling mean for acute:chronic workload ratios? Br J Sports Med. 2019;53(16):988-990. doi:10.1136/bjsports-2017-098925", grade: "methodological reply", found: "Zotero", supports: "Agrees coupling induces a spurious correlation; argues the practical consequences are limited. The 'researchers still argue' side." },
22	    { id: "gabbett2019", cite: "Gabbett TJ, Hulin B, Blanch P, Chapman P, Bailey D. To couple or not to couple? For acute:chronic workload ratios and injury risk, does it really matter? Int J Sports Med. 2019;40(9):597-600. doi:10.1055/a-0955-5589", grade: "single-cohort observational study", found: "Zotero", supports: "In 28 elite cricket fast bowlers, coupled and uncoupled ratios gave similar injury associations." },
23	  ],
24	  slides: [
25	    {
26	      role: "hook", time: 45,
27	      notes: `Open on the number. If you have been around load monitoring in the last ten years, you have heard "1.5". It comes from the acute:chronic workload ratio: this week's load divided by what the athlete has averaged over the last month or so.
28	
29	The 2016 review that popularized it called 0.8 to 1.3 a "sweet spot" and 1.5 and above a "danger zone". That framing traveled fast, into apps, dashboards and staff meetings. Today is about what is worth keeping from it.`,
30	      build(s) {
31	        s.figure("1.5", { x: 0.7, y: 1.05, w: 5.6, h: 4.4, size: 280, refs: ["gabbett2016"] });
32	        s.headline("The most quoted number in load monitoring.", { x: 6.9, y: 1.9, w: 5.7, h: 1.6, size: 40 });
33	        s.lead("It compares this week's load with what an athlete is used to. Above 1.5 became shorthand for danger.", { x: 6.9, y: 3.75, w: 5.5, h: 1.6, size: 22 });
34	        s.source("Gabbett, Br J Sports Med, 2016", { x: 6.9, y: 5.95, w: 5.5, refs: ["gabbett2016"] });
35	      },
36	    },
37	    {
38	      role: "problem", time: 60,
39	      notes: `Here is the problem. What spread was the simple version: keep everyone between 0.8 and 1.3 and injuries go down.
40	
41	What came after was messier. Reviews of the studies found the results inconsistent and often confusing. And the usual way of calculating the ratio counts this week in both the top and the bottom of the fraction, so the two move together whether or not anything real is going on. Researchers still argue about how much that matters in practice.
42	
43	None of this means load does not matter. It means a single ratio is not a verdict on an athlete.`,
44	      build(s) {
45	        s.headline("The number got simple. The science didn't.", { y: 1.2, w: 11.5, h: 0.9, size: 44 });
46	        s.label("What spread", { x: 0.75, y: 2.75, w: 5.2 });
47	        s.text(0.75, 3.2, 5.3, 2.4, "Stay between 0.8 and 1.3 and injuries go down.", { font: "light", size: 30, lineH: 1.12 });
48	        s.line(6.62, 2.8, 6.62, 5.7, { color: "rule", w: 1 });
49	        s.label("What later work found", { x: 7.1, y: 2.75, w: 5.4 });
50	        s.text(7.1, 3.2, 5.45, 2.6, "Results are inconsistent, and this week sits on both sides of the ratio, so some of the link is arithmetic.", { font: "light", size: 25, lineH: 1.15 });
51	        s.source("Gabbett 2016 · Impellizzeri et al. 2020 · Lolli et al. 2019", { refs: ["gabbett2016", "impellizzeri2020", "lolli2019"] });
52	        s.cite("windt2019", "gabbett2019");
53	      },
54	    },
55	    {
56	      role: "insight", time: 75,
57	      notes: `What holds up is the idea underneath the number. Athletes tolerate hard work they have built up to. What gets them in trouble is a sudden jump well beyond what they are used to.
58	
59	Read the scale left to right. 1.0 means this week looks like a normal week for that athlete. The shaded band is "close to usual". From 1.5 up is a spike: half again more than they are prepared for. In the rugby league data, players with a solid base handled ordinary weeks well, and their risk rose with spikes.
60	
61	So the ratio is a way to spot spikes. That is its job, and that is where its job ends.`,
62	      build(s) {
63	        s.headline("Sudden spikes are the risk, not hard work.", { y: 1.2, w: 11.6, h: 0.9, size: 44 });
64	        const X = r => 1.25 + (r - 0.5) * 7.0;
65	        const y = 4.6;
66	        s.rect(X(0.8), y - 0.62, X(1.3) - X(0.8), 0.78, { fill: "soft" });
67	        s.line(X(0.5), y, X(2.0) + 0.35, y, { color: "muted", w: 1.25 });
68	        s.line(X(1.5), y, X(2.0) + 0.35, y, { color: "accent", w: 7 });
69	        [0.5, 0.8, 1.0, 1.3, 1.5, 2.0].forEach(r => {
70	          const major = [0.5, 1.0, 1.5, 2.0].includes(r);
71	          const hot = r === 1.5;
72	          s.line(X(r), y - (major ? 0.14 : 0.09), X(r), y + (major ? 0.14 : 0.09), { color: hot ? "accent" : "muted", w: major ? 1.5 : 1 });
73	          s.text(X(r) - 0.6, y + 0.3, 1.2, 0.45, r.toFixed(1), { font: "cond", size: major ? 22 : 16, align: "center", color: hot ? "accent" : major ? "ink" : "muted" });
74	        });
75	        s.text(X(0.8), y - 1.2, 3.6, 0.45, "0.8–1.3: close to usual", { font: "cond", size: 20, color: "muted" });
76	        s.text(X(1.5), y - 1.2, 3.8, 0.45, "1.5 and up: a spike", { font: "condBold", size: 20, color: "accent" });
77	        s.text(X(0.5), y + 0.95, 4, 0.4, "Less than usual", { font: "light", size: 16, color: "muted" });
78	        s.text(X(2.0) + 0.35 - 4, y + 0.95, 4, 0.4, "More than usual", { font: "light", size: 16, color: "muted", align: "right" });
79	        s.source("Lines as drawn in Gabbett 2016; spike finding from Hulin et al. 2016", { refs: ["gabbett2016", "hulin2016"] });
80	      },
81	    },
82	    {
83	      role: "application", time: 60,
84	      notes: `So how do we use it here? As a question, not a red light. Three steps, in order.
85	
86	First, know where the jumps live: the first days of camp, the return from an injury, the week back from a break. Those are predictable.
87	
88	Second, when the number jumps, ask why. Was it planned, or did it creep up through extra sessions nobody added up?
89	
90	Third, any change to a plan goes through the people who own it: the sport coach, and Athletic Medicine for anyone in rehab or return to play. The number starts the conversation. It never ends it.`,
91	      build(s) {
92	        s.headline("Use it as a question, not a red light.", { y: 1.2, w: 11.5, h: 0.9, size: 44 });
93	        const cols = [
94	          ["1", "Know where jumps live: camp, breaks, returns from injury."],
95	          ["2", "When it jumps, ask: planned, or crept up?"],
96	          ["3", "Bring in the coach and Athletic Medicine."],
97	        ];
98	        cols.forEach(([k, t], i) => {
99	          const x = 0.75 + i * 4.0;
100	          s.line(x, 2.95, x + 3.55, 2.95, { color: "rule", w: 1 });
101	          s.text(x, 3.15, 1.2, 0.8, k, { font: "cond", size: 40, color: "muted", lineH: 0.9 });
102	          s.text(x, 4.0, 3.55, 2.0, t, { font: "light", size: 24, lineH: 1.18 });
103	        });
104	        s.line(0.75, 6.15, 12.58, 6.15, { color: "rule", w: 1 });
105	        s.cite("hulin2016");
106	      },
107	    },
108	    {
109	      role: "takeaway", time: 45,
110	      notes: `One line to take away: ramp, don't spike.
111	
112	The big jumps are on the calendar before they happen: the first week of camp, the week back from a break. If we plan those weeks on purpose, we get the benefit of hard work without the jump.
113	
114	Question for the room: where in our calendar does load jump without anyone planning it? Give people a moment; the answers are usually specific and useful.`,
115	      build(s) {
116	        s.headline("Ramp, don't spike.", { y: 1.35, w: 11.5, h: 1.8, size: 104 });
117	        s.lead("Spikes show up on the calendar first. Plan those weeks on purpose.", { y: 3.45, w: 9.2, h: 1.3, size: 24 });
118	        s.line(0.75, 5.0, 1.75, 5.0, { color: "accent", w: 3 });
119	        s.text(0.75, 5.2, 11.8, 1.0, "Where in our calendar does load jump without anyone planning it?", { font: "medium", size: 26, color: "accent", lineH: 1.15 });
120	      },
121	    },
122	  ],
123	};
