// 36 · Chronotype and Training: the same session lands differently on early and late body clocks.
// Composition: hook = one short question, nothing else but a source; takeaway = huge
// headline, short accent rule, question below; alignment = left. Problem = full-height soft
// panel on the right third; application = two-row-plus "when / do" table on hairlines.

module.exports = {
  num: 36,
  slug: "chronotype-and-training",
  title: "Chronotype and Training",
  category: "Emerging / Wildcard Topics",
  palette: "charcoal",
