// 37 · Gut-Brain Axis: the connection is real; most of what's claimed about it comes from mice.
// Composition: hook = one word at 104pt with a narrow lead beneath; takeaway = the question
// alone, centered, in accent; alignment = center (insight and takeaway centered). Problem =
// bare type on open ground; application = three unnumbered lines with generous leading.

module.exports = {
  num: 37,
  slug: "gut-brain-axis",
  title: "Gut-Brain Axis",
  category: "Emerging / Wildcard Topics",
  palette: "night",
  hero: { layout: "two-node-channels", concept: "Gut and brain as two plain circles joined by three two-way channels: nerves, immune signals, chemical messengers" },
  compose: { hook: "single-word", takeaway: "question-only", align: "center" },
  oneIdea: "Gut and brain talk in both directions. Stress upsetting the gut is something we see every week; gut microbes shaping mood is mostly shown in mice so far.",
  question: "Who hears first when an athlete's stomach is off before competition?",
  caveats: `Be explicit that most mechanism work on the microbiota-gut-brain axis comes from animal models, especially mice; Cryan et al. (2019) say animal models have been "paramount" and that human studies are ongoing. The probiotic meta-analysis (Liu et al. 2019, 34 trials) found small effects on depression (d = -0.24) and very small effects on anxiety (d = -0.10), larger in clinical samples. Those are not athlete studies and not a reason to recommend a product. Marttinen et al. (2020) conclude that adequately powered, high-quality athlete trials are still needed. Probiotics are supplements: any athlete considering one goes through the sports dietitian, since supplements carry contamination and quality risks (IOC consensus, Maughan et al. 2018). Do not suggest probiotics as treatment for anxiety or depression; anything clinical goes to Athletic Medicine and Baylor's licensed mental health staff. The 30-50% figure is for gut complaints during exercise, mainly in endurance athletes.`,
  sources: [
    { id: "cryan2019", cite: "Cryan JF, O'Riordan KJ, Cowan CSM, et al. The microbiota-gut-brain axis. Physiol Rev. 2019;99(4):1877-2013. doi:10.1152/physrev.00018.2018", grade: "comprehensive narrative review", found: "external", supports: "Microbiota and brain communicate via the immune system, tryptophan metabolism, the vagus nerve and enteric nervous system, and microbial metabolites; stress affects the axis; animal models have been paramount and human studies are ongoing." },
    { id: "clark2016", cite: "Clark A, Mach N. Exercise-induced stress behavior, gut-microbiota-brain axis and diet: a systematic review for athletes. J Int Soc Sports Nutr. 2016;13:43. doi:10.1186/s12970-016-0155-6", grade: "systematic review", found: "external", supports: "Exercise and psychological stress activate stress hormones and immune signals that act on the gut; much of the microbiota evidence comes from murine models." },
    { id: "liu2019", cite: "Liu RT, Walsh RFL, Sheehan AE. Prebiotics and probiotics for depression and anxiety: a systematic review and meta-analysis of controlled clinical trials. Neurosci Biobehav Rev. 2019;102:13-23. doi:10.1016/j.neubiorev.2019.03.023", grade: "meta-analysis (34 controlled trials)", found: "external", supports: "Prebiotics did not differ from placebo; probiotics had small effects on depression (d = -0.24) and anxiety (d = -0.10)." },
    { id: "marttinen2020", cite: "Marttinen M, Ala-Jaakkola R, Laitila A, Lehtinen MJ. Gut microbiota, probiotics and physical performance in athletes and physically active individuals. Nutrients. 2020;12(10):2936. doi:10.3390/nu12102936", grade: "narrative review", found: "external", supports: "Probiotics may help athletes, but high-quality, adequately powered clinical studies are still needed." },
    { id: "deoliveira2014", cite: "de Oliveira EP, Burini RC, Jeukendrup A. Gastrointestinal complaints during exercise: prevalence, etiology, and nutritional recommendations. Sports Med. 2014;44(Suppl 1):S79-S85. doi:10.1007/s40279-014-0153-2", grade: "narrative review", found: "external", supports: "Studies suggest 30-50% of athletes experience gastrointestinal complaints, especially in endurance sport; nutrition training and choices can reduce them." },
    { id: "jeukendrup2017", cite: "Jeukendrup AE. Training the gut for athletes. Sports Med. 2017;47(Suppl 1):101-110. doi:10.1007/s40279-017-0690-6", grade: "narrative review", found: "external", supports: "The gut is adaptable: gastric emptying and stomach comfort can be trained by practicing intake." },
    { id: "maughan2018", cite: "Maughan RJ, Burke LM, Dvorak J, et al. IOC consensus statement: dietary supplements and the high-performance athlete. Int J Sport Nutr Exerc Metab. 2018;28(2):104-125. doi:10.1123/ijsnem.2018-0020", grade: "consensus statement", found: "external", supports: "Supplements make at most a minor contribution and carry risks; use should follow expert advice." },
  ],
  slides: [
    {
      role: "hook", time: 45,
      notes: `One word to start: mice. You have probably seen the headlines: gut bacteria control your mood, a healthy gut means a calm mind, this probiotic will sharpen focus.

Much of the science behind those headlines was first shown in mice, often mice raised without any gut bacteria at all. That research is careful and important. It just isn't the same as evidence in twenty-year-old athletes. Today is about what we can say with confidence, and what we can't yet.`,
      build(s) {
        s.headline([{ t: "Mice.", color: "accent" }], { y: 1.45, w: 8, h: 1.75, size: 104 });
        s.lead("Much of the gut-brain story you’ve heard was first shown in them, not in athletes.", { y: 3.5, w: 6, h: 1.3, size: 24 });
        s.source("Cryan et al., Physiological Reviews, 2019", { y: 5.9, w: 7, refs: ["cryan2019", "clark2016"] });
      },
    },
    {
      role: "problem", time: 55,
      notes: `Here is where the human evidence stands. A meta-analysis pooled thirty-four controlled trials of prebiotics and probiotics for depression and anxiety. Prebiotics did no better than placebo. Probiotics did a little better, small effects on mood scores, larger in people with a diagnosis. That is real, and it is modest.

And almost none of it is in athletes. A review of probiotics in athletes concluded that well-designed, properly sized trials are still needed.

So when a product promises a calmer, sharper athlete through the gut, the honest answer is: not shown yet.`,
      build(s) {
        s.headline("In people, the effects are real but small.", { y: 1.3, w: 9.5, h: 1.6, size: 52 });
        s.lead("Across 34 trials, probiotics shifted mood scores only slightly. Athlete trials are few and small.", { y: 3.35, w: 8.2, h: 1.4, size: 28, color: "ink" });
        s.source("Liu et al., Neurosci Biobehav Rev, 2019 · Marttinen et al., Nutrients, 2020", { y: 5.9, w: 9, refs: ["liu2019", "marttinen2020"] });
      },
    },
    {
      role: "insight", time: 75,
      notes: `What does hold up is the connection itself. The gut and the brain are linked by three kinds of channel: nerves, mainly the vagus nerve; immune signals; and chemical messengers, including hormones and substances made by gut bacteria.

And the line runs both ways. The direction we can see in people every week is brain to gut: stress and nerves change how the gut works. That is the athlete who can't eat before a big game, or who has stomach trouble on the bus.

The other direction, gut bacteria shaping mood and thinking, is where the mouse evidence is strong and the human evidence is still early.`,
      build(s) {
        s.headline("The line runs both ways.", { x: 0.75, y: 1.3, w: 11.83, h: 1.0, size: 56, align: "center" });
        s.lead("Stress upsets the gut; we see that every week. Gut microbes shaping mood is still mostly shown in mice.", { x: 2.2, y: 2.4, w: 8.93, h: 0.95, size: 22, align: "center" });
        const cy = 4.85, r = 0.78, gx = 3.0, bx = 10.33;
        s.circle(gx, cy, r, { line: "ink", lineW: 1.5 });
        s.circle(bx, cy, r, { line: "ink", lineW: 1.5 });
        s.text(gx - r, cy - 0.25, 2 * r, 0.5, "Gut", { font: "condBold", size: 24, align: "center", valign: "middle" });
        s.text(bx - r, cy - 0.25, 2 * r, 0.5, "Brain", { font: "condBold", size: 24, align: "center", valign: "middle" });
        [["Nerves", -0.62], ["Immune signals", 0], ["Chemical messengers", 0.62]].forEach(([t, dy]) => {
          const y = cy + dy + 0.12;
          s.line(gx + r + 0.25, y, bx - r - 0.25, y, { color: "accent", w: 2, arrow: "both" });
          s.text(4.4, y - 0.42, 4.53, 0.36, t, { font: "cond", size: 18, color: "muted", align: "center" });
        });
        s.source("Channels: Cryan et al. 2019 · Stress and the gut: Clark & Mach 2016", { x: 0.75, y: 6.15, w: 11.83, align: "center", refs: ["cryan2019", "clark2016"] });
      },
    },
    {
      role: "application", time: 65,
      notes: `So start with the gut problems we can actually see. Three of them.

Gut trouble around exercise is common. Reviews suggest somewhere between a third and a half of athletes report it, mostly in endurance sport. Treat it as real, not as nerves to push through.

The gut can be trained. Athletes who practice their game-day food and fluids in training tolerate them better on game day. That is a nutrition conversation, and our sports dietitians own it.

And probiotics: they are supplements, the evidence is mixed, and supplements carry quality risks. Any athlete thinking about one goes through the sports dietitian first.`,
      build(s) {
        s.headline("Start with the gut problems we can see.", { y: 1.2, w: 11.5, h: 0.9, size: 44 });
        const lines = [
          "Treat stomach trouble around competition as common and real.",
          "Practice game-day food and fluids in training.",
          "Send probiotic questions to the sports dietitian.",
        ];
        lines.forEach((t, i) => s.text(0.75, 2.75 + i * 1.12, 11.6, 0.6, t, { font: "light", size: 28, lineH: 1.1 }));
        s.source("de Oliveira et al. 2014 · Jeukendrup 2017 · Maughan et al. 2018", { y: 6.05, w: 9, refs: ["deoliveira2014", "jeukendrup2017", "maughan2018"] });
      },
    },
    {
      role: "takeaway", time: 45,
      notes: `The line to take away: the gut-brain connection is real, and the part we can act on today is the stress-and-stomach side, not a supplement.

So the question for the room: who hears first when an athlete's stomach is off before competition? A coach, an athletic trainer, a dietitian, a teammate? And does that information get to the people who can help, including Athletic Medicine and, when stress is part of it, Baylor's licensed mental health staff?`,
      build(s) {
        s.text(1.4, 2.0, 10.53, 3.2, "Who hears first when an athlete’s stomach is off before competition?", { font: "medium", size: 52, color: "accent", lineH: 1.1, align: "center", valign: "middle" });
      },
    },
  ],
};

