// 38 · Breathwork Techniques: slow breathing for calm is well supported; most bigger claims are not yet.
// Composition: hook = what's claimed vs what's measured, two plain columns; takeaway = line
// top-left, question flush right in the lower half; alignment = left. Problem = hairline rows;
// application = one "do this Monday" sentence at 40pt with one line under it.

module.exports = {
  num: 38,
  slug: "breathwork-techniques",
  title: "Breathwork Techniques",
  category: "Emerging / Wildcard Topics",
  palette: "sage",
  hero: { layout: "evidence-lollipops", concept: "Five popular breathing claims as lollipops whose length is the depth of evidence behind them: slow breathing for calm is long, mouth taping is short" },
  compose: { hook: "assume-vs-measured", takeaway: "question-right", align: "left" },
  oneIdea: "Slow breathing reliably calms the body in the moment, and that is worth teaching. Most bigger breathwork claims rest on one or two small trials.",
  question: "Which breathing claims are already going around our locker rooms?",
  caveats: `The lollipop lengths on slide 3 are our reading of how much evidence sits behind each claim (number and type of studies), not a statistical score, and the slide says so. "Calms heart rhythm" means higher vagally mediated heart rate variability during and after slow breathing (Laborde et al. 2022, 223 studies); that is a physiological marker, not proof of better performance. The stress meta-analysis (Fincham et al. 2023) pooled 12 trials with 785 adults, mostly at moderate risk of bias, and its authors warn against a "miscalibration between hype and evidence". The cyclic sighing finding is one remote trial (Balban et al. 2023), and the slow-breathing sleep finding is one trial of 64 young adults (Laborde et al. 2019); both are promising, not settled. Mouth taping: a 2025 scoping review found nine heterogeneous studies, mostly in people with sleep apnea or snoring, and little consensus on benefit. Breathing-muscle training with a resistance device (HajGhanbari et al. 2013) is a different thing: 21 trials suggest it can improve some endurance performance measures, with small samples; mention it only if asked. Safety: hyperventilation and breath-holding (as in some Wim Hof-style practices) must never be done in or near water; the New York review found 16 blackout cases linked to these behaviors.`,
  sources: [
    { id: "laborde2022", cite: "Laborde S, Allen MS, Borges U, et al. Effects of voluntary slow breathing on heart rate and heart rate variability: a systematic review and a meta-analysis. Neurosci Biobehav Rev. 2022;138:104711. doi:10.1016/j.neubiorev.2022.104711", grade: "systematic review and meta-analysis (223 studies)", found: "external", supports: "Voluntary slow breathing increases vagally mediated HRV during a session, immediately after one session, and after multi-session interventions; low-cost with few adverse effects." },
    { id: "fincham2023", cite: "Fincham GW, Strauss C, Montero-Marin J, Cavanagh K. Effect of breathwork on stress and mental health: a meta-analysis of randomised-controlled trials. Sci Rep. 2023;13(1):432. doi:10.1038/s41598-022-27247-y", grade: "meta-analysis (12 RCTs, 785 adults)", found: "external", supports: "Breathwork lowered self-reported stress versus controls (g = -0.35); most studies at moderate risk of bias; authors caution against hype." },
    { id: "laborde2019", cite: "Laborde S, Hosang T, Mosley E, Dosseville F. Influence of a 30-day slow-paced breathing intervention compared to social media use on subjective sleep quality and cardiac vagal activity. J Clin Med. 2019;8(2):193. doi:10.3390/jcm8020193", grade: "single randomized trial (64 young adults)", found: "Zotero", supports: "15 minutes of slow-paced breathing each evening for 30 days improved self-rated sleep quality and overnight cardiac vagal activity compared with social media use." },
    { id: "balban2023", cite: "Balban MY, Neri E, Kogon MM, et al. Brief structured respiration practices enhance mood and reduce physiological arousal. Cell Rep Med. 2023;4(1):100895. doi:10.1016/j.xcrm.2022.100895", grade: "single remote randomized trial", found: "external", supports: "Five minutes a day of cyclic sighing improved mood and lowered respiratory rate more than mindfulness meditation; compared three techniques with different results." },
    { id: "fangmeyer2025", cite: "Fangmeyer SK, Badger CD, Thakkar PG. Nocturnal mouth-taping and social media: a scoping review of the evidence. Am J Otolaryngol. 2025;46(1):104545. doi:10.1016/j.amjoto.2024.104545", grade: "scoping review (9 studies)", found: "external", supports: "Literature is heterogeneous with little consensus on benefits; few social media claims about mouth taping have been tested." },
    { id: "boyd2015", cite: "Boyd C, Levy A, McProud T, et al. Fatal and nonfatal drowning outcomes related to dangerous underwater breath-holding behaviors - New York State, 1988-2011. MMWR Morb Mortal Wkly Rep. 2015;64(19):518-521.", grade: "public health case review (16 cases)", found: "external", supports: "Intentional hyperventilation and prolonged breath-holding before or during swimming led to unconsciousness underwater and drownings." },
    { id: "hajghanbari2013", cite: "HajGhanbari B, Yamabayashi C, Buna TR, et al. Effects of respiratory muscle training on performance in athletes: a systematic review with meta-analyses. J Strength Cond Res. 2013;27(6):1643-1663. doi:10.1519/JSC.0b013e318269f73f", grade: "systematic review with meta-analyses (21 RCTs)", found: "external", supports: "Respiratory muscle training improved some sport performance outcomes; samples small and protocols varied. A separate practice from breathwork; for questions only." },
  ],
  slides: [
    {
